import{_ as r}from"./chunks/export-dialog.gVHeZ16Q.js";import{_ as a,o,c as d,a2 as e}from"./chunks/framework.Dx-TCpNt.js";const u=JSON.parse('{"title":"エクスポート","description":"エクスポートは、コマとノートの集まりを、読める・印刷できる・共有できる形に変えます。学習用の HTML ドキュメント、スライド用の PNG 画像、別のマシン用のプロジェクトパッケージです。","frontmatter":{"description":"エクスポートは、コマとノートの集まりを、読める・印刷できる・共有できる形に変えます。学習用の HTML ドキュメント、スライド用の PNG 画像、別のマシン用のプロジェクトパッケージです。"},"headers":[],"relativePath":"ja/guide/export.md","filePath":"ja/guide/export.md","lastUpdated":1794725747000}'),s={name:"ja/guide/export.md"};function n(i,t,l,h,g,c){return o(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="エクスポート" tabindex="-1">エクスポート <a class="header-anchor" href="#エクスポート" aria-label="Permalink to &quot;エクスポート&quot;">​</a></h1><p>エクスポートは、コマとノートの集まりを、読める・印刷できる・共有できる形に変えます。学習用の HTML ドキュメント、スライド用の PNG 画像、別のマシン用のプロジェクトパッケージです。</p><figure class="shot"><img src="'+r+'" alt="レイアウトテンプレート、範囲、言語、画像の扱い、ライブプレビューを備えたエクスポートダイアログ"><figcaption>エクスポートダイアログ。左の列でドキュメントを設定し、右側でレイアウトをプレビューします。区切り線をドラッグすると幅を変更できます。</figcaption></figure><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>ノートはアプリの中に、コマに紐付いて存在します。タブレットで見直したり、印刷したり、比較をスライドに貼ったりするには、ページ画像と対応するノートを一緒に保った可搬な成果物が必要です。しかも、何もアップロードせずに。</p><h2 id="ダイアログを開く" tabindex="-1">ダイアログを開く <a class="header-anchor" href="#ダイアログを開く" aria-label="Permalink to &quot;ダイアログを開く&quot;">​</a></h2><p><code>E</code> を押すか、上部バーの <strong>エクスポート</strong> をクリックします。ダイアログは常に、表示中のページまたは話をエクスポートします。</p><h2 id="html-エクスポート" tabindex="-1">HTML エクスポート <a class="header-anchor" href="#html-エクスポート" aria-label="Permalink to &quot;HTML エクスポート&quot;">​</a></h2><h3 id="タイトルと範囲" tabindex="-1">タイトルと範囲 <a class="header-anchor" href="#タイトルと範囲" aria-label="Permalink to &quot;タイトルと範囲&quot;">​</a></h3><table tabindex="0"><thead><tr><th>コントロール</th><th>動作</th></tr></thead><tbody><tr><td><strong>タイトル</strong></td><td>ドキュメントのタイトル。推奨ファイル名にも使われます。</td></tr><tr><td><strong>現在のページ</strong></td><td>開いているページだけをエクスポートします。</td></tr><tr><td><strong>話全体（n ページ）</strong></td><td>話の中で注釈のあるすべてのページをエクスポートします。</td></tr><tr><td><strong>ノートのあるページだけ</strong></td><td>ノートのないページを飛ばします。学習ノートのまとめに便利です。</td></tr><tr><td><strong>言語</strong></td><td>ドキュメントに表示する言語。</td></tr></tbody></table><h3 id="画像の扱い" tabindex="-1">画像の扱い <a class="header-anchor" href="#画像の扱い" aria-label="Permalink to &quot;画像の扱い&quot;">​</a></h3><table tabindex="0"><thead><tr><th>モード</th><th>動作</th></tr></thead><tbody><tr><td><strong>同名の <code>.files</code> フォルダ</strong>（既定）</td><td>HTML は隣のフォルダの画像を参照します。軽く、読み込みも速くなります。両方を一緒にコピーしてください。</td></tr><tr><td><strong>単一ファイルにまとめる</strong></td><td>画像を data URL として埋め込みます。共有するファイルは1つですが、話全体では数十 MB になることがあります。</td></tr></tbody></table><p><strong>原画にコマ枠を描く</strong> は、エクスポートする原画にコマの矩形を重ねます。これは注釈とは独立しています。</p><p><strong>これらのタグを含む注釈だけ書き出す</strong> はタグでノートを絞り込み、<strong>絞り込みを解除</strong> は選択を解除します。</p><h3 id="レイアウト" tabindex="-1">レイアウト <a class="header-anchor" href="#レイアウト" aria-label="Permalink to &quot;レイアウト&quot;">​</a></h3><p>組み込みのレイアウトテンプレートは3つあります。</p><table tabindex="0"><thead><tr><th>テンプレート</th><th>結果</th></tr></thead><tbody><tr><td><strong>左画像・右注釈</strong></td><td>左に漫画ページ、右にページとコマのノート。</td></tr><tr><td><strong>上画像・下注釈</strong></td><td>画像が全幅に広がり、ノートが下に展開されます。</td></tr><tr><td><strong>コマ比較</strong></td><td>各コマに複数言語を並べ、そのノートを添えます。</td></tr></tbody></table><p>レイアウトテンプレートは任意の名前で保存し、JSON としてエクスポートし、再びインポートできます。<code>data/templates/export.json</code> に保存されます。レイアウトのコントロールは次のとおりです。</p><table tabindex="0"><thead><tr><th>コントロール</th><th>効果</th></tr></thead><tbody><tr><td><strong>画像列の幅</strong></td><td>画像列の幅（パーセント）。</td></tr><tr><td><strong>列の間隔</strong></td><td>画像とノートの間隔。</td></tr><tr><td><strong>文字サイズ</strong></td><td>ドキュメントの基本フォント倍率。</td></tr><tr><td><strong>1行あたりの列数</strong></td><td>1行に並べるページブロックの数。</td></tr></tbody></table><p>レイアウトは自動で記憶されます。ライブプレビューの区切り線をドラッグして画像幅を設定することもできます。</p><h3 id="生成" tabindex="-1">生成 <a class="header-anchor" href="#生成" aria-label="Permalink to &quot;生成&quot;">​</a></h3><ol><li>範囲、言語、画像の扱い、レイアウトを選びます。</li><li><strong>HTML を生成</strong> をクリックします。</li><li>完了すると、エクスポートしたページ数とファイルの場所が表示されます。</li><li><strong>HTML を開く</strong> でブラウザで開くか、<strong>HTML をダウンロード</strong> でコピーを保存します。既定の画像モードでは、<code>.files</code> フォルダも一緒にコピーしてください。</li></ol><p>ファイルはプロジェクトの <code>exports/</code> フォルダに書き出されます。HTML はディスクから直接開けます。</p><h3 id="印刷" tabindex="-1">印刷 <a class="header-anchor" href="#印刷" aria-label="Permalink to &quot;印刷&quot;">​</a></h3><p>生成された HTML には印刷用スタイルが含まれます。背景は削除され、ページ幅は制限されず、ページブロックは画像の途中で分割されません。ブラウザでファイルを開き、通常の <strong>印刷</strong> コマンドで、ブラウザの印刷ダイアログから PDF を作成してください。</p><div class="tip custom-block"><p class="custom-block-title">PDF への印刷</p><p>現在 PDF を得る正式な方法は、ブラウザの「PDF として保存」です。ネイティブの PDF エクスポーターは実装されていません。<a href="/KomaYomi-docs/ja/guide/project-files">プロジェクトファイルと形式</a> を参照してください。</p></div><h2 id="png-エクスポート" tabindex="-1">PNG エクスポート <a class="header-anchor" href="#png-エクスポート" aria-label="Permalink to &quot;PNG エクスポート&quot;">​</a></h2><p><strong>PNG を書き出し</strong> セクションは、ドキュメントを介さずに画像を生成します。</p><table tabindex="0"><thead><tr><th>モード</th><th>内容</th></tr></thead><tbody><tr><td><strong>ページ全体</strong></td><td>コマ枠と注釈を付けたページ画像。</td></tr><tr><td><strong>現在のコマ</strong></td><td>選択したコマを切り取り、位置合わせした画像。</td></tr><tr><td><strong>3言語コラージュ</strong></td><td>同じコマ（コマを選択していない場合はページ全体）について、選択した言語を並べた画像。</td></tr></tbody></table><p>オプション:</p><ul><li><strong>注釈を含める（n）</strong> — 注釈レイヤーを PNG に描画します。件数は含まれるマークの数を示します。</li><li>ページ全体と現在のコマの PNG は <strong>優先言語（下地画像）</strong> を使い、コラージュは選択した比較言語を使います。</li><li><strong>現在のコマ</strong> は、ワークベンチでコマを選択するまで無効です。</li></ul><p>PNG はブラウザで生成され、ブラウザのダウンロードフォルダに保存されます。スライド、文書、チャットにそのまま貼れます。</p><h2 id="エクスポートテンプレート" tabindex="-1">エクスポートテンプレート <a class="header-anchor" href="#エクスポートテンプレート" aria-label="Permalink to &quot;エクスポートテンプレート&quot;">​</a></h2><p>エクスポートテンプレート（<code>.mnexp</code>）はレイアウトとスタイルの設定を保存し、同じ見た目を再利用・共有できるようにします。テンプレートのエクスポートとインポートは、サイドバーの <strong>交換ファイル…</strong> から行います。インポートしたテンプレートは検証され、元のファイルは <code>data/backups/exchange/</code> にバックアップされます。</p><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>HTML の画像が壊れている。</strong> 既定のモードでは、<code>.files</code> フォルダを HTML と一緒に移動する必要があります。一緒に移動してください。</li><li><strong>単一ファイルのエクスポートが巨大になる。</strong> 想定どおりです。すべての画像が埋め込まれます。話全体には <code>.files</code> モードを使ってください。</li><li><strong>エクスポートにページが出てこない。</strong> ノートがなく <strong>ノートのあるページだけ</strong> がオンになっているか、選択した言語の画像がないページです。</li><li><strong>PNG にコマ枠がない。</strong> PNG エクスポートは注釈の切り替えを使います。<strong>注釈を含める</strong> を有効にしてください。コマ枠は注釈ではなくコマの矩形から描かれる点に注意してください。</li><li><strong>印刷結果が切れる。</strong> ブラウザの印刷倍率を「ページに合わせる」にし、網掛けが必要な場合だけ背景のグラフィックを有効にしてください。</li><li><strong>出力フォルダに書き込めない。</strong> パッケージ化したデスクトップ版では、<code>exports/</code> は選択したライブラリフォルダの中にあります。</li></ul><figure class="shot"><div class="shot-missing"><strong>スクリーンショット未掲載：エクスポートした HTML と PNG の結果</strong> ブラウザで表示した生成済み HTML と、3つの PNG モードを並べたスクリーンショットを、ここに追加する予定です。 </div><figcaption>掲載予定：エクスポートしたドキュメントと PNG の出力。</figcaption></figure><h2 id="スクリーンショット未掲載" tabindex="-1">スクリーンショット未掲載 <a class="header-anchor" href="#スクリーンショット未掲載" aria-label="Permalink to &quot;スクリーンショット未掲載&quot;">​</a></h2><table tabindex="0"><thead><tr><th>図</th><th>必要な箇所</th></tr></thead><tbody><tr><td>エクスポートした HTML ページ</td><td>2列と縦積みのレイアウト</td></tr><tr><td>PNG モードの比較</td><td>ページ全体 / コマ / コラージュ</td></tr><tr><td>エクスポートテンプレートのコントロール</td><td>保存、インポート、適用</td></tr></tbody></table><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/guide/notes">ノート</a> — ドキュメントに入る内容。</li><li><a href="/KomaYomi-docs/ja/guide/project-files">プロジェクトファイルと形式</a> — プロジェクト全体をエクスポートする場合。</li><li><a href="/KomaYomi-docs/ja/guide/shortcuts">キーボードショートカット</a> — <code>E</code> でこのダイアログが開きます。</li></ul>',41)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
